import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int t = Integer.parseInt(br.readLine());while (t-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int l = Integer.parseInt(st.nextToken());int r = Integer.parseInt(st.nextToken());int[] a = new int[n];st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());Arrays.sort(a);out.println(countPairs(a, r) - countPairs(a, l - 1));}out.flush();out.close();}private static long countPairs(int[] a, int limit) {long count = 0;int left = 0;int right = a.length - 1;while (left < right) {if (a[left] + a[right] <= limit) {count += (right - left);left++;} else {right--;}}return count;}}